import { useState } from 'react';
import { TokenSearchField } from '@kerfjs/ui/token-search-field';

type FilterToken = { id: string; label: string; value: string };
type SearchModel = { text: string; tokens: FilterToken[] };
type Props = { initialValue: SearchModel; parse: (text: string) => SearchModel; suggestions: (model: SearchModel) => string[]; onSearch: (model: SearchModel) => void };

export function WorkspaceSearch({ initialValue, parse, suggestions, onSearch }: Props) {
  const [model, setModel] = useState(initialValue);

  function change(next: SearchModel) {
    setModel(next);
    onSearch(next);
  }

  return (
    <TokenSearchField
      aria-label="Search workspace"
      value={model.text}
      tokens={model.tokens}
      suggestions={suggestions(model)}
      onValueChange={(text: string) => change({ ...model, text })}
      onParse={(text: string) => change(parse(text))}
      onTokenRemove={(id: string) => change({ ...model, tokens: model.tokens.filter(token => token.id !== id) })}
      onTokenReplace={(id: string, token: FilterToken) => change({ ...model, tokens: model.tokens.map(current => current.id === id ? token : current) })}
      onClear={() => change({ text: '', tokens: [] })}
      restoreCaretOnEdit
    />
  );
}
